<template><div><div class="page-heading"><div><h2>组织空间</h2><p>为学院、社团和职能部门建立独立的活动管理空间。</p></div><el-button type="primary" @click="visible=true">新增组织</el-button></div><div class="surface" v-loading="loading"><div class="toolbar"><el-input v-model="query.keyword" placeholder="查找组织" clearable @keyup.enter="search"/><el-button @click="search">查询</el-button></div><p v-if="error" role="alert">{{error}} <el-button @click="load">重试</el-button></p><el-table :data="rows"><el-table-column prop="code" label="组织编码" min-width="140"/><el-table-column prop="name" label="组织名称" min-width="200"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.status===1?'success':'info'">{{row.status===1?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="发布策略" min-width="170"><template #default="{row}"><el-button link @click="policy(row)">{{row.requireReview ? "审核后发布" : "允许直接发布"}}</el-button></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link :disabled="row.orgId===1" @click="toggle(row)">{{row.status===1?'停用':'启用'}}</el-button></template></el-table-column></el-table><el-pagination layout="total,prev,pager,next" :total="total" :page-size="query.size" :current-page="query.current" @current-change="page"/><p class="note">停用组织后，其管理员无法继续访问，公开活动报名与签到也会关闭。</p></div><el-dialog v-model="visible" title="新增组织" width="440px"><el-form label-position="top"><el-form-item label="组织编码"><el-input v-model="form.code" maxlength="40" placeholder="2至40位字母、数字或下划线"/></el-form-item><el-form-item label="组织名称"><el-input v-model="form.name" maxlength="100" placeholder="例如 计算机学院学生会"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="create">创建空间</el-button></template></el-dialog></div></template>
<script setup>
import {onMounted,ref,reactive} from 'vue'
import {organizationApi} from '../../api'
import {ElMessage} from 'element-plus'
import {usePagedResource} from '../../composables/usePagedResource'
const {rows,total,loading,error,query,load,search,page}=usePagedResource(organizationApi.page,{keyword:''})
const visible=ref(false),saving=ref(false),form=reactive({code:'',name:''})
async function create(){if(saving.value)return;if(!/^[A-Za-z0-9_]{2,40}$/.test(form.code)||!form.name.trim()){ElMessage.warning('请填写有效编码和名称');return}saving.value=true;try{await organizationApi.create(form);visible.value=false;Object.assign(form,{code:'',name:''});await load()}catch{}finally{saving.value=false}}
async function toggle(row){try{await organizationApi.status(row.orgId,row.status===1?0:1);await load()}catch{}}
async function policy(row){try{await organizationApi.reviewPolicy(row.orgId,!row.requireReview);await load()}catch{}}
onMounted(load)
</script><style scoped>.note{font-size:12px;color:#8b9ba2;margin-top:20px}</style>
